#!/bin/bash
# REIMPORT — regenerate every committed Lean netlist datum and byte-compare.
#
# ## Why this file exists
#
# Each `Imported/*.lean` datum carries the line "GENERATED by import_netlist.py"
# — and until 2026-08-06 the COMMAND that generated it was recorded nowhere. The
# input net order is not derivable from the netlist (it is the caller's choice,
# and D3.5's proofs depend on it bit-for-bit), so "regenerated" was not a thing
# anyone could actually do. The orders below were recovered by reading the bit
# assignments back out of `SwitchRefinement.lean` and re-deriving them until the
# output matched byte-for-byte.
#
# That makes this script two things at once:
#   * the PROVENANCE record — the missing half of "GENERATED by".
#   * a REGRESSION TEST — any importer change that perturbs a committed datum
#     fails here, which is how the flop treatment was shown not to disturb the
#     two combinational imports that predate it.
#
# Usage:  ./reimport.sh          check committed data are reproducible (default)
#         ./reimport.sh --write  regenerate in place (after an INTENDED change)
set -u
cd "$(dirname "$0")/../../.." || exit 2
IMP=SaltWorks/Silicon/Importer/import_netlist.py
OUT=SaltWorks/Silicon/Imported
MODE=${1:-check}
TMP=$(mktemp -d); trap 'rm -rf "$TMP"' EXIT
fail=0; n=0

seq8() { python3 -c "print(','.join(f'$1[{i}]' for i in range(8)))"; }

run() {  # run <name> <lean-basename> <netlist> <top> <inputs> <outputs>
  local name=$1 base=$2 nl=$3 top=$4 ins=$5 outs=$6
  n=$((n+1))
  python3 "$IMP" "$nl" --top "$top" --out "$TMP/$base" --name "$name" \
      --inputs "$ins" --outputs "$outs" >"$TMP/$base.log" 2>&1
  if [ $? -ne 0 ]; then
    echo "  ✗ $base — importer FAILED"; sed 's/^/      /' "$TMP/$base.log"; fail=1; return
  fi
  if [ "$MODE" = "--write" ]; then
    cp "$TMP/$base" "$OUT/$base"; echo "  ↻ $base written"
  elif cmp -s "$TMP/$base" "$OUT/$base"; then
    echo "  ✅ $base reproduces byte-for-byte"
  else
    echo "  ✗ $base DIFFERS from committed"; fail=1
  fi
}

echo "reimport: regenerating committed netlist data"

# --- comparator: 8-bit min/max, PURELY COMBINATIONAL (0 flops). ------------
run comparatorNL Comparator.lean SaltWorks/Silicon/Flow/comparator_nl.v comparator \
    "$(seq8 a),$(seq8 b)" "$(seq8 lo),$(seq8 hi)"

# --- bitserial switch: 4 flops, cut BY HAND before the treatment existed. --
# Input order is load-bearing: SwitchRefinement.lean's `switchSpec` indexes
# 0=rst_n 1=act_stb 2=sel_stb 3=in0 4=in1 5=act0 6=act1 7=sel0 8=sel1, and the
# last four are flop Q nets. Outputs are out0,out1 then the four flop D nets, so
# the caller's manual cut already paired state with next-state by position —
# which is exactly what the flop treatment now does automatically.
run switchNL Switch.lean SaltWorks/Silicon/Flow/bitserial_switch_nl.v bitserial_switch \
    "rst_n,act_stb,sel_stb,in0,in1,act0,act1,sel0,sel1" \
    "out0,out1,_00_,_01_,_02_,_03_"

# NOTE: RefComparator.lean is NOT listed — it is hand-written on purpose, a
# structurally different reference design so that agreeing with the imported
# netlist is a real check rather than a tautology. Adding it here would be a
# category error.
#
# NOTE: Fabric.lean is NOT listed either, and that is a provenance decision, not
# an oversight. Its source is `tt_submission/tt_um_saltworks_banyan.v` — a CI
# BUILD ARTIFACT from run 31140274735, not a file in this repository. A check
# that silently regenerated it from whatever copy happened to be on disk would
# assert reproducibility it cannot establish. See Flow-docs/flop-treatment-0806.md
# for the pinned artifact identity and the exact command.

echo "reimport: $n datum(s), $( [ $fail -eq 0 ] && echo "ALL REPRODUCE" || echo "FAILURES ABOVE" )"
exit $fail
